import 'package:freezed_annotation/freezed_annotation.dart';

part 'exercise_mapping.freezed.dart';
part 'exercise_mapping.g.dart';

/// Maps a GymBro exercise to a strength standard with confidence score.
///
/// Generated by semantic matching script (sentence-transformers/all-MiniLM-L6-v2).
/// Three tiers: auto (≥80%), review (60-80%), fallback (<60%).
@freezed
abstract class ExerciseMapping with _$ExerciseMapping {
  const factory ExerciseMapping({
    /// GymBro exercise ID
    required String gymbroId,

    /// GymBro exercise name
    required String gymbroName,

    /// GymBro equipment type
    required String gymbroEquipment,

    /// GymBro muscle focus (e.g., "PETT, TRIC") - nullable for exercises without defined focus
    String? gymbroFocus,

    /// Semantic similarity confidence (0.0-1.0)
    required double confidence,

    /// Mapping status: "auto", "review", or "fallback"
    required MappingStatus status,

    /// Strength standard ID (null if fallback)
    String? standardId,

    /// Strength standard name (null if fallback)
    String? standardName,

    /// Strength standard equipment (null if fallback)
    String? standardEquipment,

    /// Data source (null if fallback)
    String? dataSource,

    /// Fallback reason (only for fallback status)
    String? fallbackReason,
  }) = _ExerciseMapping;

  factory ExerciseMapping.fromJson(Map<String, dynamic> json) =>
      _$ExerciseMappingFromJson(json);
}

/// Mapping status indicating confidence level
enum MappingStatus {
  /// Auto-approved match (≥80% confidence)
  @JsonValue('auto')
  auto,

  /// Requires manual review (60-80% confidence)
  @JsonValue('review')
  review,

  /// Low confidence, use fallback (<60%)
  @JsonValue('fallback')
  fallback,

  /// Manually verified correct mapping
  @JsonValue('verified')
  verified;

  bool get isReliable => this == auto || this == verified;
  bool get needsReview => this == review;
  bool get isFallback => this == fallback;
  bool get isVerified => this == verified;
}

/// Extension to help with mapping decisions
extension ExerciseMappingExtension on ExerciseMapping {
  /// Whether this mapping can be used for weight suggestions
  bool get canSuggestWeight =>
      status == MappingStatus.auto ||
      status == MappingStatus.review ||
      status == MappingStatus.verified;

  /// Confidence as percentage (0-100)
  double get confidencePercent => confidence * 100;

  /// User-friendly status label
  String getStatusLabel(String locale) {
    switch (status) {
      case MappingStatus.auto:
        return locale.startsWith('it') ? 'Automatico' : 'Auto';
      case MappingStatus.review:
        return locale.startsWith('it') ? 'Da Verificare' : 'Review';
      case MappingStatus.fallback:
        return locale.startsWith('it') ? 'Default' : 'Fallback';
      case MappingStatus.verified:
        return locale.startsWith('it') ? 'Verificato' : 'Verified';
    }
  }

  /// Get confidence tier for UI display
  ConfidenceTier get confidenceTier {
    if (confidence >= 0.90) return ConfidenceTier.excellent;
    if (confidence >= 0.80) return ConfidenceTier.good;
    if (confidence >= 0.70) return ConfidenceTier.fair;
    if (confidence >= 0.60) return ConfidenceTier.low;
    return ConfidenceTier.veryLow;
  }
}

/// Confidence tier for UI representation
enum ConfidenceTier {
  excellent, // ≥90%
  good, // 80-90%
  fair, // 70-80%
  low, // 60-70%
  veryLow, // <60%
}
